package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;

final class GroupApprovalsBrowserAcceptance {
 static void approve(BrowserTest h,Page page,String name,String path){h.login(page,name);page.navigate(h.base()+path);page.getByLabel("Review comment").fill("Verified current group proposal");page.getByLabel("Decision",new Page.GetByLabelOptions().setExact(true)).selectOption("approved");ServiceOutagesBrowserAcceptance.click(page,"Record decision");assertThat(page.locator("main")).containsText("Verified current group proposal");}
 static void run(BrowserTest h)throws Exception {
  var f=GroupApprovalsAcceptance.seed(h.store,"GroupBrowser"+id());String record="/record/"+f.get("table")+"/"+f.get("id"),path=record+"/approvals";
  try(var p=Playwright.create();var browser=p.chromium().launch();var admin=browser.newContext();var one=browser.newContext();var two=browser.newContext()){
   var page=admin.newPage();h.login(page,"admin");page.navigate(h.base()+path);page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Configure ordered review teams").setExact(true)).press("Enter");page.getByLabel("Target state").selectOption("2");page.getByLabel("Review team 1",new Page.GetByLabelOptions().setExact(true)).selectOption(f.get("g1").toString());page.getByLabel("Review team 2",new Page.GetByLabelOptions().setExact(true)).selectOption(f.get("g2").toString());ServiceOutagesBrowserAcceptance.click(page,"Save review policy");assertThat(page.locator("main")).containsText("Technical review team");ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/group-policy-light.png")).setFullPage(true));page.navigate(h.base()+path);page.getByLabel("Reason for team review").fill("Verify technical readiness before owner review");ServiceOutagesBrowserAcceptance.click(page,"Request current review team");assertThat(page.locator("main")).containsText(f.get("a").toString()+" · requested");ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/group-stages-light.png")).setFullPage(true));
   approve(h,one.newPage(),f.get("a").toString(),path);page.reload();ServiceOutagesBrowserAcceptance.click(page,"Dark mode");page.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/group-stages-mobile-diagnostic.png")).setFullPage(true));assertEquals(false,page.evaluate("document.documentElement.scrollWidth>window.innerWidth"),"Page overflow: "+page.evaluate("Array.from(document.querySelectorAll('body *')).filter(e=>e.getBoundingClientRect().right>window.innerWidth+1).map(e=>e.tagName+'.'+e.className).slice(0,20)"));assertEquals(false,page.evaluate("Array.from(document.querySelectorAll('main .panel')).some(p=>p.scrollWidth>p.clientWidth+1)"),"Panel overflow");assertThat(page.locator("main")).containsText(f.get("b").toString()+" · withdrawn");page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/group-stages-dark.png")).setFullPage(true));page.getByLabel("Reason for team review").fill("Technical stage passed; obtain service-owner review");ServiceOutagesBrowserAcceptance.click(page,"Request current review team");approve(h,two.newPage(),f.get("c").toString(),path);page.reload();assertThat(page.locator("[data-approval-target='2']")).containsText("Approval requirement met");ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/group-stages-approved-dark.png")).setFullPage(true));page.navigate(h.base()+record);page.getByLabel("State").selectOption("2");ServiceOutagesBrowserAcceptance.click(page,"Save changes →");try(var db=h.store.open()){PlatformFoundationTest.bind(db);assertEquals("2",object(Service.readRecord(db,f.get("table").toString(),f.get("id").toString()).get("data")).get("state"));}
   page.navigate(h.base()+"/admin/approval-policies/"+f.get("table"));page.getByLabel("Target state").selectOption("2");ServiceOutagesBrowserAcceptance.click(page,"Save review policy");assertThat(page.locator("main")).containsText("Minimum independent approvals: 0");
  }
 }
}
